package com.nbi.beneficiary.model;

public class Beneficiary {
    private String id;            // BEN-77
    private String accountNumber; // beneficiary's account
    private String nickname;      // "Landlord"
    private String ifsc;

    public Beneficiary(String id, String accountNumber, String nickname, String ifsc) {
        this.id = id; this.accountNumber = accountNumber;
        this.nickname = nickname; this.ifsc = ifsc;
    }
    public String getId() { return id; }
    public String getAccountNumber() { return accountNumber; }
    public void setAccountNumber(String a) { this.accountNumber = a; }
    public String getNickname() { return nickname; }
    public void setNickname(String n) { this.nickname = n; }
    public String getIfsc() { return ifsc; }
    public void setIfsc(String i) { this.ifsc = i; }
}
