package com.nbi.beneficiary.service;

import com.nbi.beneficiary.model.Beneficiary;
import com.nbi.beneficiary.dto.*;
import org.springframework.stereotype.Service;
import java.util.*;

@Service
public class BeneficiaryService {
    private final Map<String, Beneficiary> store = new HashMap<>();

    public BeneficiaryService() {
        store.put("BEN-77", new Beneficiary("BEN-77", "SAV2001", "Rajesh", "NBI0001234"));
    }

    public Optional<Beneficiary> find(String id) { return Optional.ofNullable(store.get(id)); }

    public Beneficiary create(String id, BeneficiaryRequest r) {
        Beneficiary b = new Beneficiary(id, r.accountNumber(), r.nickname(), r.ifsc());
        store.put(id, b);
        return b;
    }

    // PUT: full replacement, every field overwritten.
    public Beneficiary replace(String id, BeneficiaryRequest r) {
        Beneficiary b = new Beneficiary(id, r.accountNumber(), r.nickname(), r.ifsc());
        store.put(id, b);
        return b;
    }

    // PATCH: only non-null fields change.
    public Optional<Beneficiary> patch(String id, PatchRequest r) {
        Beneficiary b = store.get(id);
        if (b == null) return Optional.empty();
        if (r.accountNumber() != null) b.setAccountNumber(r.accountNumber());
        if (r.nickname() != null) b.setNickname(r.nickname());
        if (r.ifsc() != null) b.setIfsc(r.ifsc());
        return Optional.of(b);
    }

    public boolean delete(String id) { return store.remove(id) != null; }
    public boolean exists(String id) { return store.containsKey(id); }
}
