// ─── File: src/main/java/com/nbi/beneficiary/controller/BeneficiaryController.java ───
package com.nbi.beneficiary.controller;

import com.nbi.beneficiary.dto.*;
import com.nbi.beneficiary.model.Beneficiary;
import com.nbi.beneficiary.service.BeneficiaryService;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import jakarta.validation.Valid;
import java.net.URI;
import java.util.Set;

@RestController
@RequestMapping("/api/v1/beneficiaries")
public class BeneficiaryController {

    private final BeneficiaryService service;
    public BeneficiaryController(BeneficiaryService service) { this.service = service; }

    // GET — safe, idempotent, cacheable
    @GetMapping("/{id}")
    public ResponseEntity<Beneficiary> get(@PathVariable String id) {
        return service.find(id).map(ResponseEntity::ok)
                .orElse(ResponseEntity.notFound().build());
    }

    // POST — create, not idempotent, returns 201 + Location
    @PostMapping("/{id}")
    public ResponseEntity<Beneficiary> create(@PathVariable String id,
                                              @Valid @RequestBody BeneficiaryRequest r) {
        Beneficiary b = service.create(id, r);
        return ResponseEntity.created(URI.create("/api/v1/beneficiaries/" + id)).body(b);
    }

    // PUT — full replace, idempotent
    @PutMapping("/{id}")
    public ResponseEntity<Beneficiary> replace(@PathVariable String id,
                                               @Valid @RequestBody BeneficiaryRequest r) {
        return ResponseEntity.ok(service.replace(id, r));
    }

    // PATCH — partial update
    @PatchMapping("/{id}")
    public ResponseEntity<Beneficiary> patch(@PathVariable String id,
                                             @RequestBody PatchRequest r) {
        return service.patch(id, r).map(ResponseEntity::ok)
                .orElse(ResponseEntity.notFound().build());
    }

    // DELETE — idempotent, 204 No Content
    @DeleteMapping("/{id}")
    public ResponseEntity<Void> delete(@PathVariable String id) {
        service.delete(id);
        return ResponseEntity.noContent().build();
    }

    // HEAD — existence check, no body
    @RequestMapping(value = "/{id}", method = RequestMethod.HEAD)
    public ResponseEntity<Void> head(@PathVariable String id) {
        return service.exists(id) ? ResponseEntity.ok().build()
                                  : ResponseEntity.notFound().build();
    }

    // OPTIONS — report allowed methods
    @RequestMapping(value = "/{id}", method = RequestMethod.OPTIONS)
    public ResponseEntity<Void> options(@PathVariable String id) {
        return ResponseEntity.ok()
                .allow(HttpMethod.GET, HttpMethod.PUT, HttpMethod.PATCH,
                       HttpMethod.DELETE, HttpMethod.HEAD, HttpMethod.OPTIONS)
                .build();
    }
}
```
